import styles from "./rich-text-information-container.module.less";
import { RichText, RichTextType } from "@/core/components/primitives/rich-text/rich-text";
import { multipleClassNames } from "@/core/helpers/string-helper";
import { STANDARD_INFORMATION, SUCCESS_INFORMATION, WARNING_INFORMATION } from "./rich-text-information-types";

const RichTextInformationContainer = ({
  informationProps,
  informationType = STANDARD_INFORMATION,
  className,
}: {
  informationProps: RichTextType;
  informationType?: string;
  className?: string;
}) => {
  const getInformationTypeClass = () => {
    switch (informationType) {
      case SUCCESS_INFORMATION:
        return styles.success;
      case WARNING_INFORMATION:
        return styles.warning;
      default:
        return styles.standard;
    }
  };

  return (
    <div className={multipleClassNames(getInformationTypeClass(), className)}>
      <RichText richText={informationProps} />
    </div>
  );
};

export default RichTextInformationContainer;
