import { Meta, StoryObj } from "@storybook/react";
import RichTextInformationContainer from "./rich-text-information-container";
import { STANDARD_INFORMATION, SUCCESS_INFORMATION, WARNING_INFORMATION } from "./rich-text-information-types";
import { RichTextType } from "@/core/components/primitives/rich-text/rich-text";
import { ShowcaseLayout, Variant, showcaseParameters } from "@/storybook/preview";

// Small builders for Contentful rich text documents, so the stories stay readable.
const text = (value: string, marks: Array<{ type: string }> = []) => ({ nodeType: "text", value, marks, data: {} });
const block = (nodeType: string, content: Array<object>) => ({ nodeType, data: {}, content });
const paragraph = (...content: Array<object>) => block("paragraph", content);
const heading = (value: string) => block("heading-3", [text(value)]);
const document = (...content: Array<object>): RichTextType => ({
  raw: JSON.stringify({ nodeType: "document", data: {}, content }),
  references: [],
});

const meta = {
  title: "Primitives/Rich Text Information Container",
  component: RichTextInformationContainer,
  parameters: {
    docs: {
      description: {
        component:
          "Rich text inside a colored box. The background color comes from `informationType` " +
          "(standard, success or warning). Used in the group admission calendar for sold out event dates.",
      },
    },
  },
  argTypes: {
    informationType: {
      control: "select",
      options: [STANDARD_INFORMATION, SUCCESS_INFORMATION, WARNING_INFORMATION],
    },
  },
  args: {
    informationProps: document(
      heading("Utsålt!"),
      paragraph(text("Alla biljetter till denna dag är "), text("slutsålda", [{ type: "bold" }]), text(".")),
    ),
    informationType: STANDARD_INFORMATION,
  },
} satisfies Meta<typeof RichTextInformationContainer>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {};

export const VariantTypes: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout title="informationType" variantType="prop">
      <Variant label="STANDARD_INFORMATION (default)">
        <RichTextInformationContainer {...args} informationType={STANDARD_INFORMATION} />
      </Variant>
      <Variant label="SUCCESS_INFORMATION">
        <RichTextInformationContainer {...args} informationType={SUCCESS_INFORMATION} />
      </Variant>
      <Variant label="WARNING_INFORMATION">
        <RichTextInformationContainer {...args} informationType={WARNING_INFORMATION} />
      </Variant>
    </ShowcaseLayout>
  ),
};
